INSERT INTO papers (id,title,authors_json,published,updated,url,version,source_type,abstract,topics_json,verification_status,featured,created_at) VALUES ('2507.21509','Persona Vectors: Monitoring and Controlling Character Traits in Language Models','["Runjin Chen","Andy Arditi","Henry Sleight","Owain Evans","Jack Lindsey"]','2025-07-29','2025-09-05','https://arxiv.org/abs/2507.21509v3','v3','paper','Introduces prompt-elicited persona vectors for monitoring and controlling character traits. The limitations propose unsupervised SAE discovery, while Appendix M decomposes previously identified persona vectors.','["Persona discovery","Sparse autoencoders"]','Primary source reviewed',0,'2026-09-14T21:37:53.610Z') ON CONFLICT(id) DO UPDATE SET title=excluded.title,authors_json=excluded.authors_json,published=excluded.published,updated=excluded.updated,url=excluded.url,version=excluded.version,source_type=excluded.source_type,abstract=excluded.abstract,topics_json=excluded.topics_json,verification_status=excluded.verification_status,featured=excluded.featured;
INSERT INTO papers (id,title,authors_json,published,updated,url,version,source_type,abstract,topics_json,verification_status,featured,created_at) VALUES ('2512.23988','Fantastic Reasoning Behaviors and Where to Find Them: Unsupervised Discovery of the Reasoning Process','["Zhenyu Zhang","Shujian Zhang","John Lambert","Wenxuan Zhou","Zhangyang Wang","Mingqing Chen","Andrew Hard","Rajiv Mathews","Lun Wang"]','2025-12-30','','https://arxiv.org/abs/2512.23988v1','v1','paper','RISE studies SAE features of reasoning behavior. It is related methodological work; it does not establish the proposed comparison between discovered persona features and prompt-elicited persona vectors.','["Persona discovery","Sparse autoencoders"]','Primary source reviewed',0,'2026-09-14T21:37:53.610Z') ON CONFLICT(id) DO UPDATE SET title=excluded.title,authors_json=excluded.authors_json,published=excluded.published,updated=excluded.updated,url=excluded.url,version=excluded.version,source_type=excluded.source_type,abstract=excluded.abstract,topics_json=excluded.topics_json,verification_status=excluded.verification_status,featured=excluded.featured;
INSERT INTO questions (id,title,area,status,origin,summary,why_it_matters,source_json,closest_work_json,uncertainty,search_json,executable,estimated_cost_usd,estimated_minutes,access,position_json,created_at) VALUES ('q-unsupervised-persona','Can SAEs reveal persona tendencies that prompting struggles to recover?','Persona discovery','Unassessed','user-proposed','Reuse a published SAE on Qwen2.5-7B-Instruct to discover candidate behavioral directions without selecting trait labels first. Test whether those directions cause consistent changes on fresh scenarios, and compare them with optimized prompting and prompt-extracted persona vectors.','The original method needs a named trait that the model can express when prompted. This experiment asks whether label-free feature selection can reveal a useful behavioral direction outside what that extraction procedure reliably recovers. Discovery of a candidate is not proof of a new persona.','{"paperId":"2507.21509","url":"https://arxiv.org/html/2507.21509v3#S8","version":"v3","section":"Section 8, Supervised, prompt-elicited extraction; Appendix M","passage":"SAEs may therefore enable unsupervised discovery of persona-relevant directions, including specific traits that cannot be easily elicited through prompting."}','[{"paperId":"2507.21509","finding":"Appendix M studies SAE features associated with existing persona vectors.","mismatch":"Selecting features from already named trait vectors does not test discovery without a trait target."},{"paperId":"2512.23988","finding":"RISE explores reasoning behaviors using sparse autoencoders.","mismatch":"Reasoning behavior discovery does not establish generalizable persona effects that outperform a strong prompt-extraction baseline."}]','This is a proposed extension, not an established open problem or a novelty claim. Candidate names, rubrics, steering strengths and baselines must be frozen using development data before confirmation. The Kaggle runner is separate from the existing API experiment evaluator. No persona-discovery results are available yet.','{"date":"2026-09-14","queries":[],"coverage":"Targeted review of the supplied Persona Vectors limitation and RISE; not a systematic literature search.","inaccessible":["Novelty has not been established by an exhaustive search."]}',0,NULL,NULL,'Kaggle GPU study; evaluator and confirmation contract pending','{"x":39,"y":33}','2026-09-14T21:37:53.610Z') ON CONFLICT(id) DO UPDATE SET title=excluded.title,area=excluded.area,status=excluded.status,origin=excluded.origin,summary=excluded.summary,why_it_matters=excluded.why_it_matters,source_json=excluded.source_json,closest_work_json=excluded.closest_work_json,uncertainty=excluded.uncertainty,search_json=excluded.search_json,executable=excluded.executable,estimated_cost_usd=excluded.estimated_cost_usd,estimated_minutes=excluded.estimated_minutes,access=excluded.access,position_json=excluded.position_json;
